B.Eb=new A.b4("Booklet Example: Convert an algorithm into C++","Reads two numbers using cin, calculates their sum, and displays the result.",'#include <iostream>\nusing namespace std;\n\nint main() {\n    int a, b, sum;\n    cout << "Enter two numbers: ";\n    cin >> a >> b;\n    sum = a + b;\n    cout << "Sum = " << sum << endl;\n    return 0;\n}',"4 7","Enter two numbers: Sum = 11","cin >> a >> b reads two integers from the user. sum = a + b performs the process, and cout displays Sum = 11.",!0)
B.Et=new A.b4("Example 2: Perimeter of a Rectangle from User Input","Translates the perimeter formula 2 * (length + width) into C++.",'#include <iostream>\nusing namespace std;\n\nint main() {\n    int length, width, perimeter;\n    cout << "Enter length and width: ";\n    cin >> length >> width;\n    perimeter = 2 * (length + width);\n    cout << "Perimeter = " << perimeter << endl;\n    return 0;\n}',"5 3","Enter length and width: Perimeter = 16","With input 5 and 3, the process computes 2 * (5 + 3) = 16.",!1)
B.Eu=new A.b4("Example 3: Swapping Two Numbers Using a Temporary Variable","Classic algorithm translation showing how to swap two variables.",'#include <iostream>\nusing namespace std;\n\nint main() {\n    int x = 10, y = 25, temp;\n    cout << "Before swap: x = " << x << ", y = " << y << endl;\n    temp = x;\n    x = y;\n    y = temp;\n    cout << "After swap:  x = " << x << ", y = " << y << endl;\n    return 0;\n}',"","Before swap: x = 10, y = 25\nAfter swap:  x = 25, y = 10","A third variable temp holds the original value of x so it is not lost when x = y is executed.",!1)
B.Eq=new A.b4("Example 4: Calculating Simple Interest","Translates Simple Interest = (P * R * T) / 100 into a working program.",'#include <iostream>\nusing namespace std;\n\nint main() {\n    int principal = 1000;\n    int rate = 5;\n    int time = 2;\n    int interest = (principal * rate * time) / 100;\n    cout << "Simple Interest = " << interest << endl;\n    return 0;\n}',"","Simple Interest = 100","Input values (1000, 5, 2) are processed by the formula and displayed via cout.",!1)
