B.EL=new A.b4("Booklet Example: Display an array value","Declares an array of 4 marks and prints the element at index 2.","#include <iostream>\nusing namespace std;\n\nint main() {\n    int marks[4] = {45, 67, 88, 92};\n    cout << marks[2];\n    return 0;\n}","","88","Index 0 is 45, index 1 is 67, and index 2 (the third element) is 88.",!0)
B.EU=new A.b4("Example 2: Printing All Array Elements Using a for Loop","Iterates through index 0 to 3 to print every element of the array.",'#include <iostream>\nusing namespace std;\n\nint main() {\n    int marks[4] = {45, 67, 88, 92};\n    for (int i = 0; i < 4; i++) {\n        cout << "marks[" << i << "] = " << marks[i] << endl;\n    }\n    return 0;\n}',"","marks[0] = 45\nmarks[1] = 67\nmarks[2] = 88\nmarks[3] = 92","A for loop starting at i = 0 with condition i < 4 visits every valid index (0, 1, 2, 3).",!1)
B.Ea=new A.b4("Example 3: Sum and Average of Array Elements","Calculates the total and average of 5 test scores stored in an array.",'#include <iostream>\nusing namespace std;\n\nint main() {\n    int scores[5] = {70, 80, 90, 85, 75};\n    int sum = 0;\n    for (int i = 0; i < 5; i++) {\n        sum += scores[i];\n    }\n    cout << "Total = " << sum << endl;\n    cout << "Average = " << sum / 5 << endl;\n    return 0;\n}',"","Total = 400\nAverage = 80","The loop adds each scores[i] to sum (400), and dividing by 5 gives the average (80).",!1)
B.EX=new A.b4("Example 4: Finding the Largest Value in an Array","Compares each element to find the maximum number in the array.",'#include <iostream>\nusing namespace std;\n\nint main() {\n    int arr[5] = {12, 45, 23, 89, 34};\n    int highest = arr[0];\n    for (int i = 1; i < 5; i++) {\n        if (arr[i] > highest) {\n            highest = arr[i];\n        }\n    }\n    cout << "Highest value = " << highest << endl;\n    return 0;\n}',"","Highest value = 89","We start with highest = arr[0] and update it whenever we find a larger element.",!1)
