B.EJ=new A.b4("Booklet Example: Access a value through a pointer","Points p to variable x and displays the value using both x and *p.","#include <iostream>\nusing namespace std;\n\nint main() {\n    int x = 20;\n    int* p = &x;\n    cout << x << endl;\n    cout << *p << endl;\n    return 0;\n}","","20\n20","int* p = &x; stores the address of x in pointer p. *p dereferences p to read the value stored in x (20).",!0)
B.EM=new A.b4("Example 2: Modifying a Variable Through a Pointer","Changes the value of x indirectly by assigning to *p.",'#include <iostream>\nusing namespace std;\n\nint main() {\n    int x = 20;\n    int* p = &x;\n    cout << "Before: x = " << x << endl;\n    *p = 99;\n    cout << "After *p = 99: x = " << x << endl;\n    return 0;\n}',"","Before: x = 20\nAfter *p = 99: x = 99","Because p points to x, assigning *p = 99 updates the value stored in x directly!",!1)
B.E2=new A.b4("Example 3: Displaying Value, Pointer Address, and Dereferenced Value","Shows the difference between x, p (address), and *p (value at address).",'#include <iostream>\nusing namespace std;\n\nint main() {\n    int score = 85;\n    int* ptr = &score;\n    cout << "Value of score: " << score << endl;\n    cout << "Address in ptr: " << ptr << endl;\n    cout << "Value via *ptr: " << *ptr << endl;\n    return 0;\n}',"","Value of score: 85\nAddress in ptr: 0x7ffee4b8\nValue via *ptr: 85","ptr holds the memory address (e.g., 0x7ffee4b8), while *ptr gets the integer 85 at that address.",!1)
B.ET=new A.b4("Example 4: Adding Two Numbers Using Pointers","Dereferences two pointers *p1 and *p2 to calculate a sum.",'#include <iostream>\nusing namespace std;\n\nint main() {\n    int a = 15, b = 25;\n    int* p1 = &a;\n    int* p2 = &b;\n    int sum = *p1 + *p2;\n    cout << "Sum using pointers = " << sum << endl;\n    return 0;\n}',"","Sum using pointers = 40","*p1 retrieves 15 and *p2 retrieves 25, so *p1 + *p2 = 40.",!1)
