B.ES=new A.b4("Booklet Example: Write a line to a file","Uses ofstream to write student data into student.txt and closes the file.",'#include <iostream>\n#include <fstream>\nusing namespace std;\n\nint main() {\n    ofstream outFile("student.txt");\n    outFile << "Name: Ali" << endl;\n    outFile << "Marks: 85" << endl;\n    outFile.close();\n    cout << "Data saved";\n    return 0;\n}',"","Data saved",'ofstream outFile("student.txt") opens student.txt for writing. outFile << writes two lines into the file, and outFile.close() saves and closes it.',!0)
B.E3=new A.b4("Example 2: Saving a Course Result Card to a File","Writes multiple calculated values to result.txt using ofstream.",'#include <iostream>\n#include <fstream>\nusing namespace std;\n\nint main() {\n    ofstream file("result.txt");\n    int marks = 92;\n    file << "Subject: Programming Fundamentals" << endl;\n    file << "Score: " << marks << "/100" << endl;\n    file << "Status: Passed with Grade A" << endl;\n    file.close();\n    cout << "Result card written to result.txt!" << endl;\n    return 0;\n}',"","Result card written to result.txt!","Run this in the built-in C++ Editor to see both the console output and the virtual file result.txt!",!1)
B.Ed=new A.b4("Example 3: Writing Numbers 1 to 5 to a File Using a Loop","Combines a for loop with ofstream to log numbers into numbers.txt.",'#include <iostream>\n#include <fstream>\nusing namespace std;\n\nint main() {\n    ofstream out("numbers.txt");\n    for (int i = 1; i <= 5; i++) {\n        out << "Line " << i << ": Square = " << i * i << endl;\n    }\n    out.close();\n    cout << "5 lines written to numbers.txt";\n    return 0;\n}',"","5 lines written to numbers.txt","Just like cout <<, an ofstream object can be used inside loops to write multiple lines to a file.",!1)
B.EE=new A.b4("Example 4: Writing and Reading Back from a File","Writes a value with ofstream and reads it back with ifstream.",'#include <iostream>\n#include <fstream>\nusing namespace std;\n\nint main() {\n    ofstream outFile("score.txt");\n    outFile << 95;\n    outFile.close();\n\n    ifstream inFile("score.txt");\n    int savedScore;\n    inFile >> savedScore;\n    inFile.close();\n\n    cout << "Read from file: " << savedScore << endl;\n    return 0;\n}',"","Read from file: 95","ofstream writes 95 to score.txt, and ifstream reads it back into savedScore.",!1)
B.N4=s([B.E3,B.Ed,B.EE],t.C)
B.XS=new A.eQ("Write a program that saves your name and roll number to a file.",'Include <fstream>, create ofstream myFile("info.txt"); write your name and roll number with <<, and call myFile.close();','#include <iostream>\n#include <fstream>\nusing namespace std;\n\nint main() {\n    ofstream myFile("info.txt");\n    myFile << "Name: Ali Khan" << endl;\n    myFile << "Roll No: 101" << endl;\n    myFile.close();\n    cout << "Name and roll number saved to info.txt!" << endl;\n    return 0;\n}',"","Name and roll number saved to info.txt!")
